<?php
namespace App\Http\Controllers; use App\Domain\Admin\Services\AuditService; use App\Domain\Catalog\Models\ProductVariant; use App\Domain\Inventory\Enums\InventoryMovementType; use App\Domain\Inventory\Models\Inventory; use App\Domain\Inventory\Services\InventoryService; use Illuminate\Http\Request; use Inertia\Inertia;
class AdminInventoryController {public function __construct(private InventoryService $inventory,private AuditService $audit){} public function index(Request $r){$q=Inventory::with(['variant.product'])->orderBy('quantity_on_hand');if($r->filled('q'))$q->whereHas('variant',fn($x)=>$x->where('sku','ilike','%'.$r->q.'%')->orWhereHas('product',fn($p)=>$p->where('name','ilike','%'.$r->q.'%')));return Inertia::render('Admin/Inventory/Index',['inventories'=>$q->paginate(30)->withQueryString()]);} public function adjust(Request $r,ProductVariant $variant){$d=$r->validate(['delta'=>'required|integer|not_in:0','reason'=>'required|string|max:120','note'=>'nullable|string|max:500']);$before=$variant->inventory?->toArray();$inv=$this->inventory->adjust($variant,$d['delta'],InventoryMovementType::ManualAdjustment,trim($d['reason'].($d['note']?' — '.$d['note']:'')),'admin_user',$r->user()->id);$this->audit->record($r,'inventory.adjusted',$inv,$before,$inv->toArray());return back()->with('success','Inventory adjusted.');}}
